/* ── LANG SWITCHER CSS (iniettato una sola volta) ─────────────── */
(function injectCSS() {
  if (document.getElementById('sevenda-i18n-css')) return;
  const s = document.createElement('style');
  s.id = 'sevenda-i18n-css';
  /* Usa CSS custom properties dove disponibili, con fallback hardcoded */
  s.textContent = `
    .lang-sw {
      display: flex;
      align-items: center;
      gap: 2px;
      border: 1px solid var(--border-hi, rgba(255,255,255,.13));
      padding: 3px;
    }
    .lang-btn {
      font-family: var(--mono, 'Geist Mono', 'Fira Code', monospace);
      font-size: 10px;
      font-weight: 500;
      letter-spacing: .04em;
      padding: 5px 8px;
      background: transparent;
      border: none;
      cursor: pointer;
      color: var(--muted, #6e6e6a);
      transition: background .15s, color .15s;
      line-height: 1;
    }
    .lang-btn:hover { color: var(--text, #e8e8e6); }
    .lang-btn.active {
      background: var(--text, #e8e8e6);
      color: var(--bg, #0d0d0d);
    }
    @media (max-width: 768px) { nav > .lang-sw { display: none; } }
  `;
  document.head.appendChild(s);
})();

/* ── CORE ─────────────────────────────────────────────────────── */
(function() {
  'use strict';

  function applyLang(lang) {
    const t = SEVENDA_I18N[lang];
    if (!t) return;
    localStorage.setItem('sevenda-lang', lang);
    document.documentElement.lang = lang;

    document.querySelectorAll('[data-i18n]').forEach(el => {
      const v = t[el.dataset.i18n];
      if (v !== undefined) el.textContent = v;
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      const v = t[el.dataset.i18nHtml];
      if (v !== undefined) el.innerHTML = v;
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const v = t[el.dataset.i18nPlaceholder];
      if (v !== undefined) el.placeholder = v;
    });
    document.querySelectorAll('.lang-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.lang === lang);
    });
  }

  /* Propaga il cambio lingua al backend (RF-CAN-025): allinea
     organization.locale e customer.metadata.locale su Stripe alla scelta UI.
     Best-effort e SOLO per utenti autenticati — i visitatori anonimi e i
     re-render su page-load (doApply → applyLang) o cross-tab (evento storage)
     NON generano alcuna chiamata: la sync vive qui in setLang, non in applyLang.
     Un errore qui non deve mai regredire la UI, che ha già applicato la lingua. */
  function syncLocaleToServer(lang) {
    try {
      if (!SEVENDA_I18N[lang]) return;                       // lingua non valida → niente POST
      var auth    = window.SevendaAuth;
      var session = auth && auth.getSession ? auth.getSession() : null;
      var token   = session && session.access_token;
      if (!token) return;                                    // visitatore anonimo → solo localStorage
      var base = window.STRIPE_CONFIG && window.STRIPE_CONFIG.edgeFunctionBase;
      if (!base) return;
      fetch(base + '/set-locale', {
        method: 'POST',
        headers: {
          'Content-Type':  'application/json',
          'Authorization': 'Bearer ' + token,
        },
        body: JSON.stringify({ locale: lang }),
        keepalive: true,                                     // sopravvive a un eventuale unload/navigazione
      }).catch(function() { /* best-effort: la UI ha già applicato la lingua */ });
    } catch (e) { /* mai bloccare il cambio lingua per un errore di sync */ }
  }

  /* Esposto globalmente — usato da onclick="setLang(...)" */
  window.setLang = function(lang) { applyLang(lang); syncLocaleToServer(lang); };

  /* Lingua corrente (fallback 'en') */
  window.getLang = function() {
    return localStorage.getItem('sevenda-lang') || 'en';
  };

  /* Traduzione singola chiave — per stringhe generate via JS (es. errori,
     stati di caricamento) che non possono usare gli attributi data-i18n.
     Fallback: lingua corrente → inglese → chiave stessa. */
  window.t = function(key) {
    const lang = window.getLang();
    const table = SEVENDA_I18N[lang] || SEVENDA_I18N.en;
    if (table && table[key] !== undefined) return table[key];
    if (SEVENDA_I18N.en[key] !== undefined) return SEVENDA_I18N.en[key];
    return key;
  };

  /* Sincronizzazione cross-tab: se l'utente cambia lingua in un'altra scheda
     il cambiamento viene applicato anche in questa */
  window.addEventListener('storage', function(e) {
    if (e.key === 'sevenda-lang' && e.newValue && SEVENDA_I18N[e.newValue]) {
      applyLang(e.newValue);
    }
  });

  /* Applica al caricamento — defer garantisce che il DOM sia pronto */
  function doApply() {
    const saved = localStorage.getItem('sevenda-lang') || 'en';
    applyLang(saved);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', doApply);
  } else {
    doApply();
  }
})();
